DECLARE intent JSONB;
BEGIN
    SELECT o.evidence->'intent' INTO intent FROM git_operations o
    WHERE o.id=NEW.operation_id AND o.repository_id=NEW.repository_id
      AND o.service_principal_id IS NOT NULL;
    IF FOUND THEN
        IF NEW.ref_name IS DISTINCT FROM (intent->>'retention_ref') OR
           NEW.new_oid IS DISTINCT FROM (intent->>'target_oid') OR
           NEW.ref_name IS DISTINCT FROM ('refs/rootyard-ci/jobs/' || (intent->>'job_id')) OR
           NEW.storage_generation::text IS DISTINCT FROM (intent->>'storage_generation') THEN
            RAISE EXCEPTION 'CI service operation ref differs from exact intent' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NEW;
END

DECLARE expected_length INTEGER;
BEGIN
    SELECT CASE object_format WHEN 'sha256' THEN 64 ELSE 40 END INTO expected_length
      FROM repositories WHERE id = NEW.repository_id;
    IF expected_length IS NULL THEN
        RAISE EXCEPTION 'repository object format missing';
    END IF;
    IF TG_TABLE_NAME = 'forge_pulls' THEN
        IF length(NEW.head_oid) <> expected_length OR length(NEW.base_oid) <> expected_length
           OR (NEW.merge_commit_oid IS NOT NULL AND length(NEW.merge_commit_oid) <> expected_length) THEN
            RAISE EXCEPTION 'pull object format differs from repository';
        END IF;
    ELSIF length(NEW.commit_oid) <> expected_length THEN
        RAISE EXCEPTION 'commit object format differs from repository';
    END IF;
    RETURN NEW;
END

BEGIN
    IF TG_OP <> 'UPDATE' THEN
        RAISE EXCEPTION 'CI checkout jobs and cancellation tombstones are permanent';
    END IF;
    IF ROW(NEW.repository_id, NEW.job_id, NEW.owner_id, NEW.plan,
           NEW.issuer_token_id, NEW.credential_digest, NEW.expires_unix, NEW.created_at)
       IS DISTINCT FROM
       ROW(OLD.repository_id, OLD.job_id, OLD.owner_id, OLD.plan,
           OLD.issuer_token_id, OLD.credential_digest, OLD.expires_unix, OLD.created_at)
       OR (OLD.cancelled AND NOT NEW.cancelled)
       OR (OLD.revoked AND NOT NEW.revoked) THEN
        RAISE EXCEPTION 'CI checkout authority is immutable except monotonic cancellation/revocation';
    END IF;
    RETURN NEW;
END;

